const formulaire = document.querySelector("#ajout");
const titre = document.querySelector("#titre");
const liste = document.querySelector("#liste");
const vide = document.querySelector("#vide");
const total = document.querySelector("#total");
const retour = document.querySelector("#retour");
function compter() {
  const nombre = liste.querySelectorAll("li").length;
  total.textContent = String(nombre);
  vide.hidden = nombre !== 0;
  retour.textContent = "Activités : " + String(nombre);
}
formulaire.addEventListener("submit", function(evenement) {
  evenement.preventDefault();
  const texte = titre.value.trim();
  if (texte === "") { retour.textContent = "Écris un titre."; return; }
  const ligne = document.createElement("li");
  ligne.textContent = texte;
  liste.append(ligne);
  titre.value = "";
  compter();
});
document.querySelector("#vider").addEventListener("click", function() { liste.replaceChildren(); compter(); });
compter();

